        var stagePt = clientToStageLocal(clientX, clientY);
        var el = elementByIdFromModel(node.dataset.sporeId);
        var origin = el ? layoutPointOnStage(el) : { x: 0, y: 0 };
        var localX = stagePt.x - origin.x;
